// ═══════════════════════════════════════════════════════════════════════
//  OMIT3 — "Story Friends" — Children Helping Science (jsPsych) protocol
//  Structure mirrors the lab's Relationship Detective protocol; the task
//  itself runs inside this protocol (no separate game tab), so every click
//  lands in the CHS response data and the webcam recording covers the Why?s.
//  Generated by build/build.py — edit src/, not this file.
// ═══════════════════════════════════════════════════════════════════════

// ── TASK MODULE (design + scenes + custom plugin) ─────────────────────
/*__OMIT3_BUNDLE__*/

// ── INITIALIZE ────────────────────────────────────────────────────────
const jsPsych = initJsPsych();
const timeline = [];

// ── STUDY PARAMETERS ──────────────────────────────────────────────────
// Stimuli are served from the lab GitHub (raw). Change BASE_URL if hosting moves.
const BASE_URL = "__BASE_URL__";
const chsid = new URLSearchParams(window.location.search).get('response_uuid') || '';

// Version V1–V8 drawn at random for each session (see OMIT3_counterbalance_spec.md).
const built = OMIT3.buildTimeline(jsPsych, { baseUrl: BASE_URL, why: 'friend', video: { mid: BASE_URL + 'video/mid.mp4' } });   // why: 'all' | 'friend' | 'none'; video: { mid, end }
jsPsych.data.addProperties({ study: 'OMIT3', version: built.version, chs_response_uuid: chsid });

// ── FULLSCREEN ────────────────────────────────────────────────────────
const enter_fullscreen = {
    type: jsPsychFullscreen,
    fullscreen_mode: true,
    button_label: "Go full screen"
};

// ── VIDEO CONFIG & CONSENT ────────────────────────────────────────────
const video_config = {
    type: chsRecord.VideoConfigPlugin
};

const video_consent = {
    type: chsRecord.VideoConsentPlugin,
    PIName: "Ashley Thomas",
    institution: "Harvard University",
    PIContact: "athomas@g.harvard.edu",
    payment: "You will receive a $5 gift card for taking part in this study. You will be asked to provide your email for this purpose. Your email will remain strictly confidential and will only be used to issue payment.",
    procedures: `Your participation is completely voluntary; you and your child can choose not to take part. You and your child can agree to take part and later change your mind.
The study session takes place in your browser and is recorded through Children Helping Science (Lookit), an online platform for developmental research studies. During the study, your child will hear five short stories about cartoon characters. In each story a character learns two things during the school day (for example, that they feel sad, or a fact about an animal) and later tells one thing to one classmate and the other thing to a different classmate. Your child will then be asked which classmate the character is better friends with, and which classmate the character would want to share an ice cream cone or some candy with. Your child answers by clicking on one of two pictures, and we will ask them to tell you why they chose that one.
All responses are recorded in the study and uploaded to the listed researcher. Other than your consent, only in-study behavior is measured and recorded. You may be asked to complete a short exit survey; it is optional.
We don't believe there are any risks for your child from participating in this research. You and your child are free to choose whether to be in this study. You can ask all the questions you want before you decide. If you do choose to participate, it's okay to stop at any point during the session. We cannot promise any benefits to your child due to their participation in the study. However, we hope that your child will enjoy the stories, and your child's participation may improve our understanding of how children think about friendship.
Participation in research is completely voluntary. Your child's alternative to participating in this research study is to not participate. Your child can decide to participate, not participate, or discontinue participation at any time without penalty or loss of benefits to which your child is otherwise entitled. You and your child's decision will not be held against you.`,
    purpose: `We invite your child to take part in a research study because this study examines how children in their age range think about friendship. In particular, we are interested in whether children use what people tell each other — their feelings, their likes, or facts they have learned — to figure out how close two people are.`,
    research_rights_statement: `You are not waiving any legal claims, rights, or remedies because of your participation in this research study. If you have questions, concerns, or complaints, or think the research has hurt your child, talk to the research team at 617-384-7777. You can also contact the PI, Ashley Thomas, at athomas@g.harvard.edu. This research has been reviewed and approved by the Harvard University Area Institutional Review Board ("IRB"). You may talk to them at (617) 496-2847 or cuhs@harvard.edu if your questions, concerns, or complaints are not being answered by the research team, you cannot reach the research team, you want to talk to someone besides the research team, you have questions about your child's rights as a research subject, or you want to get information or provide input about this research.`
};

// ── EMAIL / PAYMENT ───────────────────────────────────────────────────
const email_trial = {
    type: jsPsychSurveyText,
    questions: [{
        prompt: "Please enter your email address to receive your $5 gift card:",
        name: "email",
        required: true
    }],
    on_finish: function(data) {
        jsPsych.data.addProperties({ payment_email: data.response.email });
    },
    data: { trial_type: "payment_email" }
};

// ── PRELOAD ───────────────────────────────────────────────────────────
const lists = OMIT3.assetLists();
const preload = {
    type: jsPsychPreload,
    images: lists.images,
    audio: lists.audio,
    show_progress_bar: true,
    message: "<p>Loading the stories&hellip;</p>",
    continue_after_error: true
};

// ── INSTRUCTIONS ──────────────────────────────────────────────────────
const instructions_page1 = {
    type: jsPsychHtmlButtonResponse,
    stimulus: `
        <div style="max-width: 600px; margin: 0 auto; line-height: 1.6;">
            <h2 style="text-align: center;">Important Instructions</h2>
            <p>Your child is about to hear five short stories about cartoon characters and answer a few questions about each one. It takes about 10–15 minutes.</p>
            <p>We want to know what your child genuinely thinks, so please <strong>stay neutral</strong> while your child makes their choices. Try to minimise distractions as much as possible.</p>
            <p>It is okay to encourage your child to make a decision — for example: <em>"Which one do you want to pick?"</em> or <em>"What do you think?"</em> — but please avoid pointing at or suggesting a particular answer.</p>
            <p>The stories are read aloud, so please make sure the device's <strong>sound is turned on</strong>.</p>
        </div>
    `,
    choices: ["Next"],
    data: { trial_type: "instructions_page1" }
};

const instructions_page2 = {
    type: jsPsychHtmlButtonResponse,
    stimulus: `
        <div style="max-width: 600px; margin: 0 auto; line-height: 1.6;">
            <h2 style="text-align: center;">How it works</h2>
            <p>Each page plays on its own. When a question comes up, the two characters become clickable and your child picks one by clicking (or tapping) on it. <strong>Please let your child do the clicking.</strong></p>
            <p>After some questions, your child will be asked <em>"Why do you think that?"</em> Let them tell you in their own words — this is recorded by the webcam — and then click <strong>Next</strong>.</p>
            <p>If your child didn't catch something, the <strong>"hear again"</strong> button at the bottom left replays the narration.</p>
            <p>There is a short practice round first, so there is no need to explain the rules yourself.</p>
        </div>
    `,
    choices: ["Start"],
    data: { trial_type: "instructions_page2" }
};

// ── EXIT SURVEY ───────────────────────────────────────────────────────
const exit_survey = {
    type: chsSurvey.ExitSurveyPlugin
};

// ── DEBRIEF ───────────────────────────────────────────────────────────
const debrief = {
    type: jsPsychHtmlButtonResponse,
    stimulus: `
        <div style="max-width: 800px; margin: 0 auto; line-height: 1.6;">
            <h2>Thank You — Here Is What We Were Studying</h2>
            <p>Adults treat what people tell each other as a clue to how close they are: we share our feelings, and especially our sad feelings, with the people we are closest to. In this study we asked whether children already use this clue.</p>
            <p>In each story, a character learned two things during the day — a feeling (sad or happy), a personal preference (a favorite animal), or a fact about an animal — and told one thing to one classmate and the other to a different classmate. We then asked your child which classmate the character is better friends with, and which classmate the character would want to share an ice cream cone or some candy with.</p>
            <p>We are interested in whether children think a character is closer to the classmate who was told a feeling than to the one who was told a fact; whether this is specific to sad feelings or extends to happy ones; and whether telling someone a personal preference, which is personal but not emotional, works the same way. The practice round, in which Sam shared a juice box with one straw and some cookies, helps us check that children see sharing a single ice cream cone as something you do with someone close.</p>
            <p>There are many reasons a child might give any particular answer — the most recent story they heard, which picture they liked best, or how they were feeling in the moment. This is why we look at patterns across many children and many stories. There were no right or wrong answers.</p>
            <p>You will receive a <strong>$5 Amazon gift card</strong> for taking part, sent within two weeks to the email address you provided.</p>
            <p>Thank you so much for participating! Your child's answers help us understand how children come to understand friendship.</p>
        </div>
    `,
    choices: ["Finish"]
};

// ── RECORDING ─────────────────────────────────────────────────────────
const start_rec = { type: chsRecord.StartRecordPlugin };
const stop_rec = { type: chsRecord.StopRecordPlugin };

// ── TIMELINE ──────────────────────────────────────────────────────────
timeline.push(
    enter_fullscreen,
    video_config,
    video_consent,
    email_trial,
    preload,
    instructions_page1,
    instructions_page2,
    start_rec,
    ...built.timeline,
    stop_rec,
    exit_survey,
    debrief
);

jsPsych.run(timeline);
